type Msg =
  | { kind: 'order.created';  order: Order }
  | { kind: 'invoice.issued'; invoice: Invoice };

function route(msg: Msg): Promise<void> {
  switch (msg.kind) {
    case 'order.created':  return orders.send(msg.order);    // payload narrowed
    case 'invoice.issued': return invoices.send(msg.invoice);
    default: return assertNever(msg);                         // new kind: compile error
  }
}
